css:
.d-hs-stage{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--bg);overflow:hidden}
.d-hs-card{position:relative;z-index:1;display:flex;flex-direction:column;gap:2px;width:200px;padding:14px 16px;border:1px solid var(--line);border-radius:10px;background:var(--paper);color:var(--ink);font:inherit;text-align:left;cursor:pointer;transform:translateY(0);transition:transform 280ms var(--ease-spring),border-color 180ms var(--ease-print)}
.d-hs-card:hover,.d-hs-card:focus-visible{transform:translateY(-12px);border-color:var(--ink);outline:none}
.d-hs-card:active{transform:translateY(-4px);transition-duration:120ms}
.d-hs-k{font-family:var(--font-mono);font-size:9px;letter-spacing:.08em;color:var(--faint)}
.d-hs-card b{font-size:15px;font-weight:650;letter-spacing:-.01em}
.d-hs-meta{font-size:11px;color:var(--muted)}
.d-hs-shadow{position:absolute;bottom:34px;width:170px;height:14px;border-radius:50%;background:var(--ink);opacity:.18;filter:blur(6px);transform:scale(1);transition:transform 280ms var(--ease-spring),opacity 280ms var(--ease-print),filter 280ms var(--ease-print)}
.d-hs-stage:hover .d-hs-shadow,.d-hs-card:focus-visible~.d-hs-shadow{transform:translateY(6px) scale(1.08);opacity:.1;filter:blur(11px)}
.d-hs-note{margin:0;font-size:9px;color:var(--faint)}
